using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // BREAKING CHANGE 1 — Discriminator property renamed from "Discriminator" to "$type".
            // Preserve "Discriminator" so EF Core 9 can read the 500K existing documents
            // and so direct SQL queries (WHERE c.Discriminator = …) keep working.
            entity.HasDiscriminator<string>("Discriminator");

            // BREAKING CHANGE 2 — Id format changed from "EntityType|KeyValue" to just "KeyValue".
            // Preserve the legacy "Product|<id>" format so existing documents stay addressable.
            entity.HasPartitionKey(p => p.Id);
            entity.Property(p => p.Id)
                  .ToJsonPropertyName("id")
                  .HasValueGenerator<LegacyIdValueGenerator>();
        });
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        // BREAKING CHANGE 3 — Sync I/O now throws by default.
        // Keep it enabled while migrating callers to async.
        base.OnConfiguring(optionsBuilder);
    }
}

