arguments.new_str:
class CosmosQuery
{
    // BREAKING CHANGE 3 — Sync APIs (ToList, First, Single, …) now throw
    // InvalidOperationException in the Cosmos provider.  All calls must be async.
    async Task FindProducts(ProductContext ctx)
    {
        // Direct Cosmos SQL — still works because we kept "Discriminator" as the
        // discriminator property name in OnModelCreating (see BREAKING CHANGE 1).
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";

        // Converted from sync ToList() → async ToListAsync()
        var products = await ctx.Products.Where(p => p.Sku == "ABC").ToListAsync();
    }
}

